#!/usr/bin/env python3
import re
import sys


SCRIPT_BLOCK_RE = re.compile(
    r"<\s*script\b[^>]*>.*?<\s*/\s*script\s*>",
    re.IGNORECASE | re.DOTALL,
)
SCRIPT_TAG_RE = re.compile(r"<\s*/?\s*script\b[^>]*>", re.IGNORECASE)
TAG_OR_COMMENT_RE = re.compile(r"<!--.*?-->|<[^>]+>", re.DOTALL)
EVENT_ATTR_NAME_RE = re.compile(r"(?i)^on[a-z0-9_-]+$")
JS_SCHEME_RE = re.compile(r"(?is)^(\s*)javascript\s*:\s*")


def remove_script_blocks(html: str) -> str:
    html = SCRIPT_BLOCK_RE.sub("", html)
    html = SCRIPT_TAG_RE.sub("", html)
    return html


def strip_javascript_scheme(value: str) -> str:
    return JS_SCHEME_RE.sub(r"\1", value, count=1)


def sanitize_tag(tag: str) -> str:
    if tag.startswith("<!--"):
        return tag
    if len(tag) < 3:
        return tag
    if tag[1] in "/!?":
        return tag

    end = len(tag) - 1  # final '>'
    i = 1
    out = ["<"]

    # Copy tag name exactly.
    while i < end and tag[i] not in " \t\r\n/>":
        out.append(tag[i])
        i += 1

    while i < end:
        ws_start = i
        while i < end and tag[i].isspace():
            i += 1
        ws = tag[ws_start:i]

        if i >= end:
            out.append(ws)
            break

        # Preserve self-closing slash and any trailing chunk before '>'
        if tag[i] == "/":
            out.append(ws)
            out.append(tag[i:end])
            i = end
            break

        # Parse attribute name
        name_start = i
        while i < end and (not tag[i].isspace()) and tag[i] not in "=/>":
            i += 1

        # Malformed token char; keep as-is and continue.
        if i == name_start:
            out.append(ws)
            out.append(tag[i])
            i += 1
            continue

        name = tag[name_start:i]
        lower_name = name.lower()

        # Spaces between attribute name and '=' (or next token)
        ws1_start = i
        while i < end and tag[i].isspace():
            i += 1
        ws1 = tag[ws1_start:i]

        has_eq = i < end and tag[i] == "="
        if not has_eq:
            if EVENT_ATTR_NAME_RE.match(lower_name):
                # Remove only the harmful attribute token; keep leading whitespace.
                out.append(ws)
            else:
                out.append(ws + name + ws1)
            continue

        i += 1  # consume '='

        # Spaces after '='
        ws2_start = i
        while i < end and tag[i].isspace():
            i += 1
        ws2 = tag[ws2_start:i]

        if i < end and tag[i] in "\"'":
            quote = tag[i]
            i += 1
            val_start = i
            while i < end and tag[i] != quote:
                i += 1
            value = tag[val_start:i]

            close_quote = ""
            if i < end and tag[i] == quote:
                close_quote = quote
                i += 1

            if EVENT_ATTR_NAME_RE.match(lower_name):
                out.append(ws)
            else:
                value = strip_javascript_scheme(value)
                out.append(ws + name + ws1 + "=" + ws2 + quote + value + close_quote)
        else:
            # Unquoted value
            val_start = i
            while i < end and (not tag[i].isspace()) and tag[i] != ">":
                i += 1
            value = tag[val_start:i]

            if EVENT_ATTR_NAME_RE.match(lower_name):
                out.append(ws)
            else:
                value = strip_javascript_scheme(value)
                out.append(ws + name + ws1 + "=" + ws2 + value)

    out.append(">")
    return "".join(out)


def sanitize_html(html: str) -> str:
    html = remove_script_blocks(html)
    return TAG_OR_COMMENT_RE.sub(lambda m: sanitize_tag(m.group(0)), html)


def main() -> int:
    if len(sys.argv) != 2:
        print("Usage: filter.py <html_file>", file=sys.stderr)
        return 1

    path = sys.argv[1]

    try:
        with open(path, "r", encoding="utf-8", errors="surrogateescape", newline="") as f:
            original = f.read()
    except OSError as e:
        print(f"Error reading {path}: {e}", file=sys.stderr)
        return 1

    sanitized = sanitize_html(original)

    try:
        with open(path, "w", encoding="utf-8", errors="surrogateescape", newline="") as f:
            f.write(sanitized)
    except OSError as e:
        print(f"Error writing {path}: {e}", file=sys.stderr)
        return 1

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
